// Independent, hand-written ns-3.44 reference configuration for W1.
//
// This is intentionally a separate implementation of the declared medium
// operating point.  It is not generated by the LLM pipeline and is not a
// copy of any archived generated.cc file.

#include "ns3/applications-module.h"
#include "ns3/core-module.h"
#include "ns3/csma-module.h"
#include "ns3/flow-monitor-module.h"
#include "ns3/internet-module.h"
#include "ns3/lte-module.h"
#include "ns3/mobility-module.h"
#include "ns3/network-module.h"
#include "ns3/point-to-point-module.h"
#include "ns3/wifi-module.h"

#include <fstream>
#include <map>
#include <string>

using namespace ns3;

namespace {

constexpr double kSimulationSeconds = 10.0;
constexpr uint32_t kSeed = 2;
constexpr double kOfferedLoadMbps = 10.0;
constexpr uint32_t kPacketSizeBytes = 1024;
constexpr double kMobilitySpeedMps = 3.0;
constexpr double kLiFiRateMbps = 100.0;
constexpr uint16_t kUdpPort = 9;

void ConfigureCpeMobility(const NodeContainer& cpes)
{
    MobilityHelper mobility;
    mobility.SetPositionAllocator(
        "ns3::RandomRectanglePositionAllocator",
        "X",
        StringValue("ns3::UniformRandomVariable[Min=0.0|Max=50.0]"),
        "Y",
        StringValue("ns3::UniformRandomVariable[Min=0.0|Max=50.0]"));
    mobility.SetMobilityModel(
        "ns3::RandomWalk2dMobilityModel",
        "Bounds",
        RectangleValue(Rectangle(0.0, 50.0, 0.0, 50.0)),
        "Speed",
        StringValue("ns3::ConstantRandomVariable[Constant=3.000000]"));
    mobility.Install(cpes);
}

void ConfigureFixedPosition(const NodeContainer& nodes, const Vector& position)
{
    Ptr<ListPositionAllocator> allocator = CreateObject<ListPositionAllocator>();
    allocator->Add(position);
    MobilityHelper mobility;
    mobility.SetPositionAllocator(allocator);
    mobility.SetMobilityModel("ns3::ConstantPositionMobilityModel");
    mobility.Install(nodes);
}

} // namespace

int main(int argc, char** argv)
{
    std::string outputDir = ".";
    CommandLine command;
    command.AddValue("outputDir", "Directory for the independent reference outputs", outputDir);
    command.Parse(argc, argv);

    RngSeedManager::SetSeed(kSeed);

    // The declared scenario has three CPEs and one node for each access-side
    // attachment.  The containers are deliberately explicit so the access
    // mapping can be inspected without an LLM-generated scenario wrapper.
    NodeContainer cpes;
    cpes.Create(3);
    NodeContainer wifiAp;
    wifiAp.Create(1);
    NodeContainer lifiAp;
    lifiAp.Create(1);
    NodeContainer enb;
    enb.Create(1);
    NodeContainer lteRemote;
    lteRemote.Create(1);
    NodeContainer wifiRemote;
    wifiRemote.Create(1);
    NodeContainer lifiRemote;
    lifiRemote.Create(1);

    InternetStackHelper internet;
    internet.Install(cpes);
    internet.Install(wifiAp);
    internet.Install(lifiAp);
    internet.Install(lteRemote);
    internet.Install(wifiRemote);
    internet.Install(lifiRemote);

    ConfigureCpeMobility(cpes);
    ConfigureFixedPosition(wifiAp, Vector(15.0, 25.0, 0.0));
    ConfigureFixedPosition(lifiAp, Vector(35.0, 25.0, 0.0));
    ConfigureFixedPosition(enb, Vector(25.0, 25.0, 0.0));
    MobilityHelper fixedHosts;
    fixedHosts.SetMobilityModel("ns3::ConstantPositionMobilityModel");
    fixedHosts.Install(lteRemote);
    fixedHosts.Install(wifiRemote);
    fixedHosts.Install(lifiRemote);

    PointToPointHelper backbone;
    backbone.SetDeviceAttribute("DataRate", StringValue("1Gbps"));
    backbone.SetChannelAttribute("Delay", StringValue("2ms"));
    Ipv4AddressHelper address;

    NetDeviceContainer wifiBackbone = backbone.Install(wifiRemote.Get(0), wifiAp.Get(0));
    address.SetBase("192.168.1.0", "255.255.255.0");
    Ipv4InterfaceContainer wifiBackboneIfaces = address.Assign(wifiBackbone);

    NetDeviceContainer lifiBackbone = backbone.Install(lifiRemote.Get(0), lifiAp.Get(0));
    address.SetBase("192.168.3.0", "255.255.255.0");
    Ipv4InterfaceContainer lifiBackboneIfaces = address.Assign(lifiBackbone);

    WifiHelper wifi;
    wifi.SetStandard(WIFI_STANDARD_80211n);
    YansWifiChannelHelper channel = YansWifiChannelHelper::Default();
    YansWifiPhyHelper phy;
    phy.SetChannel(channel.Create());
    WifiMacHelper mac;
    Ssid ssid("wifi-hybrid");
    mac.SetType("ns3::ApWifiMac", "Ssid", SsidValue(ssid));
    NetDeviceContainer apDevices = wifi.Install(phy, mac, wifiAp);
    mac.SetType("ns3::StaWifiMac", "Ssid", SsidValue(ssid));
    NetDeviceContainer stationDevices = wifi.Install(phy, mac, cpes);
    address.SetBase("192.168.2.0", "255.255.255.0");
    Ipv4InterfaceContainer apIfaces = address.Assign(apDevices);
    Ipv4InterfaceContainer stationIfaces = address.Assign(stationDevices);

    // LiFi is represented here by the same declared CSMA-based surrogate,
    // with no optical geometry or optical PHY model.
    CsmaHelper lifiSurrogate;
    lifiSurrogate.SetChannelAttribute("DataRate", StringValue("100Mbps"));
    lifiSurrogate.SetChannelAttribute("Delay", TimeValue(NanoSeconds(10)));
    NodeContainer lifiSegment;
    lifiSegment.Add(lifiAp);
    lifiSegment.Add(cpes);
    NetDeviceContainer lifiDevices = lifiSurrogate.Install(lifiSegment);
    address.SetBase("192.168.4.0", "255.255.255.0");
    Ipv4InterfaceContainer lifiIfaces = address.Assign(lifiDevices);

    Ptr<LteHelper> lte = CreateObject<LteHelper>();
    Ptr<PointToPointEpcHelper> epc = CreateObject<PointToPointEpcHelper>();
    lte->SetEpcHelper(epc);
    Ptr<Node> packetGateway = epc->GetPgwNode();
    NetDeviceContainer lteBackbone = backbone.Install(packetGateway, lteRemote.Get(0));
    address.SetBase("10.0.0.0", "255.0.0.0");
    Ipv4InterfaceContainer lteBackboneIfaces = address.Assign(lteBackbone);
    NetDeviceContainer baseStationDevices = lte->InstallEnbDevice(enb);
    NetDeviceContainer ueDevices = lte->InstallUeDevice(cpes);
    Ipv4InterfaceContainer ueIfaces = epc->AssignUeIpv4Address(ueDevices);
    for (uint32_t i = 0; i < cpes.GetN(); ++i)
    {
        lte->Attach(ueDevices.Get(i), baseStationDevices.Get(0));
    }

    Ipv4StaticRoutingHelper routing;
    routing.GetStaticRouting(wifiRemote.Get(0)->GetObject<Ipv4>())
        ->AddNetworkRouteTo(Ipv4Address("192.168.2.0"), Ipv4Mask("255.255.255.0"), 1);
    routing.GetStaticRouting(lifiRemote.Get(0)->GetObject<Ipv4>())
        ->AddNetworkRouteTo(Ipv4Address("192.168.4.0"), Ipv4Mask("255.255.255.0"), 1);
    routing.GetStaticRouting(lteRemote.Get(0)->GetObject<Ipv4>())
        ->AddNetworkRouteTo(Ipv4Address("7.0.0.0"), Ipv4Mask("255.0.0.0"), 1);

    const double intervalSeconds = kPacketSizeBytes * 8.0 / (kOfferedLoadMbps * 1e6);
    for (uint32_t i = 0; i < cpes.GetN(); ++i)
    {
        UdpServerHelper server(kUdpPort);
        ApplicationContainer serverApps = server.Install(cpes.Get(i));
        serverApps.Start(Seconds(0.0));
        serverApps.Stop(Seconds(kSimulationSeconds));

        UdpClientHelper wifiClient(stationIfaces.GetAddress(i), kUdpPort);
        wifiClient.SetAttribute("MaxPackets", UintegerValue(1000000));
        wifiClient.SetAttribute("Interval", TimeValue(Seconds(intervalSeconds)));
        wifiClient.SetAttribute("PacketSize", UintegerValue(kPacketSizeBytes));
        ApplicationContainer wifiApps = wifiClient.Install(wifiRemote.Get(0));
        wifiApps.Start(Seconds(1.0));
        wifiApps.Stop(Seconds(kSimulationSeconds));

        UdpClientHelper lifiClient(lifiIfaces.GetAddress(i + 1), kUdpPort);
        lifiClient.SetAttribute("MaxPackets", UintegerValue(1000000));
        lifiClient.SetAttribute("Interval", TimeValue(Seconds(intervalSeconds)));
        lifiClient.SetAttribute("PacketSize", UintegerValue(kPacketSizeBytes));
        ApplicationContainer lifiApps = lifiClient.Install(lifiRemote.Get(0));
        lifiApps.Start(Seconds(1.0));
        lifiApps.Stop(Seconds(kSimulationSeconds));

        UdpClientHelper lteClient(ueIfaces.GetAddress(i), kUdpPort);
        lteClient.SetAttribute("MaxPackets", UintegerValue(1000000));
        lteClient.SetAttribute("Interval", TimeValue(Seconds(intervalSeconds)));
        lteClient.SetAttribute("PacketSize", UintegerValue(kPacketSizeBytes));
        ApplicationContainer lteApps = lteClient.Install(lteRemote.Get(0));
        lteApps.Start(Seconds(1.0));
        lteApps.Stop(Seconds(kSimulationSeconds));
    }

    FlowMonitorHelper monitorHelper;
    Ptr<FlowMonitor> monitor = monitorHelper.InstallAll();
    Simulator::Stop(Seconds(kSimulationSeconds));
    Simulator::Run();
    monitor->CheckForLostPackets();
    monitor->SerializeToXmlFile(outputDir + "/flowmon.xml", true, true);

    std::ofstream manifest(outputDir + "/reference_manifest.csv");
    manifest << "declared_access,cpe,destination_address,port\n";
    for (uint32_t i = 0; i < cpes.GetN(); ++i)
    {
        manifest << "Wi-Fi,CPE" << (i + 1) << "," << stationIfaces.GetAddress(i) << ",9\n";
        manifest << "LiFi-surrogate,CPE" << (i + 1) << "," << lifiIfaces.GetAddress(i + 1) << ",9\n";
        manifest << "LTE/EPC,CPE" << (i + 1) << "," << ueIfaces.GetAddress(i) << ",9\n";
    }
    manifest.close();
    Simulator::Destroy();
    return 0;
}
